mapper.select:
SELECT 
    id, order_id, order_item_id, buyer_id, seller_id, after_sales_type, status, 
    reason, description, images, refund_amount, actual_refund_amount, 
    review_comment, shipping_company, tracking_number, return_note, 
    receive_status, receive_note, create_time, update_time
FROM after_sales


        AND buyer_id = #{params.buyerId}


        AND seller_id = #{params.sellerId}


        AND status = #{params.status}


        AND after_sales_type = #{params.afterSalesType}


        AND create_time >= #{params.startTime}


        AND create_time <= #{params.endTime}


ORDER BY create_time DESC

    LIMIT #{params.offset}, #{params.limit}

SELECT COUNT(*)
FROM after_sales


        AND buyer_id = #{params.buyerId}


        AND seller_id = #{params.sellerId}


        AND status = #{params.status}


        AND after_sales_type = #{params.afterSalesType}


        AND create_time >= #{params.startTime}


        AND create_time <= #{params.endTime}

